using System.Globalization;
using System.Text;

namespace ODrive.CodeGen;

public sealed record FlatProperty(string Path, AttributeDef Attribute);
public sealed record FlatFunction(string Path, FunctionDef Function);

/// <summary>Produit le code C# de src/ODrive.Model/Generated et le JSON d'endpoints de contrôle.</summary>
public sealed class Emitter(InterfaceModel model, string rootInterface)
{
    private const string Header =
        """
        // <auto-generated>
        //   Généré par tools/ODrive.CodeGen depuis ref/ODrive/Firmware/odrive-interface.yaml (tag fw-v0.5.6).
        //   Ne pas modifier à la main : relancer `dotnet run --project tools/ODrive.CodeGen`.
        // </auto-generated>
        #nullable enable

        namespace ODrive.Model;

        """;

    private readonly InterfaceDef _root = model.Interfaces[rootInterface];

    // ---------- Noms C# ----------

    // Même règle que odrivetool (ref/ODrive/tools/enums_template.j2:20) : le nom du parent ne préfixe
    // que les noms génériques → AxisError, EncoderMode, CanProtocol, mais AxisState, ControlMode.
    public static string CsEnumName(ValueTypeDef vt)
    {
        string[] parts = vt.FullName.Split('.');
        string parent = parts.Length > 1 ? parts[^2] : "";
        return (vt.Name is "Error" or "Mode" or "Protocol" ? parent : "") + vt.Name;
    }

    /// <summary>Préfixe des constantes odrivetool (enums_template.j2:13), ex. AXIS_STATE, MOTOR_ERROR.</summary>
    public string PythonPrefix(ValueTypeDef vt)
    {
        string[] parts = vt.FullName.Split('.');
        string parent = parts.Length > 1 ? parts[^2] : "";
        return model.ToMacroCase((vt.Name is "Error" or "Mode" ? parent : "") + vt.Name);
    }

    private string CsMemberName(string firmwareName)
    {
        string name = model.ToPascalCase(firmwareName);
        return char.IsDigit(name[0]) ? "_" + name : name;
    }

    private static string CsUnderlyingType(ValueTypeDef vt) => vt.JsonType switch
    {
        "uint8" => "byte",
        "uint16" => "ushort",
        "uint32" => "uint",
        _ => "ulong",
    };

    // ---------- Enums ----------

    public string EmitEnums()
    {
        var names = model.Enums.GroupBy(CsEnumName).Where(g => g.Count() > 1).Select(g => g.Key).ToList();
        if (names.Count > 0)
            throw new InvalidDataException("noms d'enum C# en double : " + string.Join(", ", names));

        var sb = new StringBuilder(Header);
        foreach (var vt in model.Enums)
        {
            sb.Append('\n');
            sb.Append($"/// <summary>{Xml(vt.FullName)} (odrivetool : {PythonPrefix(vt)}_*).</summary>\n");
            if (vt.IsFlags) sb.Append("[System.Flags]\n");
            sb.Append($"public enum {CsEnumName(vt)} : {CsUnderlyingType(vt)}\n{{\n");
            foreach (var value in vt.Values)
            {
                if (Summary(value.Brief, value.Doc) is { } summary)
                    sb.Append($"    /// <summary>{Xml(summary)}</summary>\n");
                string literal = vt.IsFlags
                    ? "0x" + value.Value.ToString("X8", CultureInfo.InvariantCulture)
                    : value.Value.ToString(CultureInfo.InvariantCulture);
                sb.Append($"    {CsMemberName(value.Name)} = {literal},\n");
            }
            sb.Append("}\n");
        }
        return sb.ToString();
    }

    public string EmitEnumMetadata()
    {
        var sb = new StringBuilder(Header);
        sb.Append("\npublic static partial class ODriveEnums\n{\n");
        sb.Append("    /// <summary>Tous les enums et flags du firmware, avec les noms et descriptions d'origine.</summary>\n");
        sb.Append("    public static System.Collections.Generic.IReadOnlyList<EnumMetadata> All { get; } =\n    [\n");
        foreach (var vt in model.Enums)
        {
            sb.Append($"        new(typeof({CsEnumName(vt)}), {Lit(vt.FullName)}, {Lit(PythonPrefix(vt))}, {Bool(vt.IsFlags)},\n        [\n");
            foreach (var value in vt.Values)
                sb.Append($"            new({Lit(value.Name)}, {value.Value.ToString(CultureInfo.InvariantCulture)}UL, {Lit(value.Brief)}, {Lit(value.Doc)}),\n");
            sb.Append("        ]),\n");
        }
        sb.Append("    ];\n}\n");
        return sb.ToString();
    }

    // ---------- Arbre aplati ----------

    public (List<FlatProperty> Properties, List<FlatFunction> Functions) Flatten()
    {
        var properties = new List<FlatProperty>();
        var functions = new List<FlatFunction>();
        Walk(_root, "");
        return (properties, functions);

        void Walk(InterfaceDef intf, string prefix)
        {
            foreach (var attr in intf.GetAllAttributes())
            {
                if (attr.Value is not null) properties.Add(new FlatProperty(prefix + attr.Name, attr));
                else Walk(attr.SubObject!, prefix + attr.Name + ".");
            }
            foreach (var func in intf.GetAllFunctions())
                functions.Add(new FlatFunction(prefix + func.Name, func));
        }
    }

    public string EmitInterfaceMetadata()
    {
        var (properties, functions) = Flatten();
        var sb = new StringBuilder(Header);
        sb.Append("\npublic static partial class ODriveInterface\n{\n");
        sb.Append("    /// <summary>Tag du firmware dont ces métadonnées sont issues.</summary>\n");
        sb.Append("    public const string FirmwareTag = \"fw-v0.5.6\";\n\n");
        sb.Append($"    /// <summary>Interface racine (ODrive v3.x : ref/ODrive/Firmware/Tupfile.lua:235).</summary>\n");
        sb.Append($"    public const string RootInterface = {Lit(rootInterface)};\n\n");

        sb.Append("    /// <summary>Toutes les propriétés, dans l'ordre des endpoints de la carte.</summary>\n");
        sb.Append("    public static System.Collections.Generic.IReadOnlyList<PropertyMetadata> Properties { get; } =\n    [\n");
        foreach (var p in properties)
        {
            var a = p.Attribute;
            sb.Append($"        new({Lit(p.Path)}, {Lit(a.Value!.JsonType)}, {Bool(!a.ReadOnly)}, {Lit(a.Unit)}, {Lit(a.Brief)}, {Lit(a.Doc)}, {EnumType(a.Value)}),\n");
        }
        sb.Append("    ];\n\n");

        sb.Append("    /// <summary>Toutes les fonctions, dans l'ordre des endpoints de la carte.</summary>\n");
        sb.Append("    public static System.Collections.Generic.IReadOnlyList<FunctionMetadata> Functions { get; } =\n    [\n");
        foreach (var f in functions)
        {
            sb.Append($"        new({Lit(f.Path)}, {Args(f.Function.Inputs)}, {Args(f.Function.Outputs)}, {Lit(f.Function.Brief)}, {Lit(f.Function.Doc)}),\n");
        }
        sb.Append("    ];\n}\n");
        return sb.ToString();

        string Args(List<ArgDef> args) =>
            "[" + string.Join(", ", args.Select(a => $"new({Lit(a.Name)}, {Lit(a.Type!.JsonType)}, {Lit(a.Doc)}, {EnumType(a.Type)})")) + "]";

        string EnumType(ValueTypeDef vt) => vt.IsEnum ? $"typeof({CsEnumName(vt)})" : "null";
    }

    // ---------- Wrappers typés ----------

    private string CsClassName(InterfaceDef intf)
    {
        string[] parts = intf.FullName.Split('.');
        if (parts.Length > 1 && parts[0] == "ODrive") parts = parts[1..];
        return string.Concat(parts.Select(model.ToPascalCase));
    }

    private static string CsValueType(ValueTypeDef vt) => vt.IsEnum ? CsEnumName(vt) : vt.JsonType switch
    {
        "bool" => "bool",
        "float" => "float",
        "int8" => "sbyte",
        "uint8" => "byte",
        "int16" => "short",
        "uint16" => "ushort",
        "int32" => "int",
        "uint32" => "uint",
        "int64" => "long",
        "uint64" => "ulong",
        "endpoint_ref" => "ODrive.Protocol.EndpointRef",
        _ => throw new InvalidDataException("type sans équivalent C# : " + vt.FullName),
    };

    /// <summary>Une classe par interface atteignable depuis la racine : propriétés, sous-objets et fonctions.</summary>
    public string EmitWrappers()
    {
        // Interfaces dans l'ordre de première visite.
        var interfaces = new List<InterfaceDef>();
        Collect(_root);
        void Collect(InterfaceDef intf)
        {
            if (interfaces.Contains(intf)) return;
            interfaces.Add(intf);
            foreach (var attr in intf.GetAllAttributes())
                if (attr.SubObject is not null) Collect(attr.SubObject);
        }

        var enumNames = model.Enums.Select(CsEnumName).ToHashSet();
        var duplicates = interfaces.GroupBy(CsClassName).Where(g => g.Count() > 1 || enumNames.Contains(g.Key))
            .Select(g => g.Key).ToList();
        if (duplicates.Count > 0)
            throw new InvalidDataException("noms de classe C# en conflit : " + string.Join(", ", duplicates));

        var sb = new StringBuilder(Header);
        sb.Append("using System.Collections.Generic;\nusing System.Threading;\nusing System.Threading.Tasks;\nusing ODrive.Protocol;\n");

        foreach (var intf in interfaces)
        {
            string className = CsClassName(intf);
            var attributes = intf.GetAllAttributes();
            var functions = intf.GetAllFunctions();
            bool isRoot = ReferenceEquals(intf, _root);

            // CS0542 : un membre ne peut pas porter le nom de sa classe (Endpoint.endpoint devient EndpointValue).
            string Member(string firmwareName)
            {
                string name = CsMemberName(firmwareName);
                return name == className ? name + "Value" : name;
            }

            var members = attributes.Select(a => Member(a.Name))
                .Concat(functions.Select(f => Member(f.Name) + "Async")).ToList();
            var clashes = members.GroupBy(m => m).Where(g => g.Count() > 1 || g.Key is "Device" or "Path")
                .Select(g => g.Key).ToList();
            if (clashes.Count > 0)
                throw new InvalidDataException($"membres en conflit dans {className} : " + string.Join(", ", clashes));

            sb.Append($"\n/// <summary>{Xml(intf.FullName)}</summary>\n");
            sb.Append($"public sealed partial class {className} : RemoteObject\n{{\n");
            if (isRoot)
                sb.Append($"    public {className}(ODriveDevice device) : this(device, \"\") {{ }}\n\n");
            sb.Append($"    public {className}(ODriveDevice device, string path) : base(device, path)\n    {{\n");
            foreach (var attr in attributes)
            {
                sb.Append(attr.Value is not null
                    ? $"        {Member(attr.Name)} = Property<{CsValueType(attr.Value)}>({Lit(attr.Name)});\n"
                    : $"        {Member(attr.Name)} = new {CsClassName(attr.SubObject!)}(device, ChildPath({Lit(attr.Name)}));\n");
            }
            sb.Append("    }\n");

            foreach (var attr in attributes)
            {
                sb.Append('\n');
                string? summary = Summary(attr.Brief, attr.Doc);
                if (attr.Unit is not null) summary = summary is null ? $"[{attr.Unit}]" : $"[{attr.Unit}] {summary}";
                if (summary is not null) sb.Append($"    /// <summary>{Xml(summary)}</summary>\n");
                string type = attr.Value is not null ? $"RemoteProperty<{CsValueType(attr.Value)}>" : CsClassName(attr.SubObject!);
                sb.Append($"    public {type} {Member(attr.Name)} {{ get; }}\n");
            }

            foreach (var func in functions)
            {
                sb.Append('\n');
                if (Summary(func.Brief, func.Doc) is { } summary)
                    sb.Append($"    /// <summary>{Xml(summary)}</summary>\n");
                string parameters = string.Concat(func.Inputs.Select(a => $"{CsValueType(a.Type!)} {CsParameterName(a.Name)}, "));
                string arguments = "[" + string.Join(", ", func.Inputs.Select(a => CsParameterName(a.Name))) + "]";
                string call = $"CallAsync({Lit(func.Name)}, {arguments}, ct)";
                string name = Member(func.Name) + "Async";
                if (func.Outputs.Count == 0)
                {
                    sb.Append($"    public Task {name}({parameters}CancellationToken ct = default) =>\n        {call};\n");
                }
                else
                {
                    string returnType = func.Outputs.Count == 1
                        ? CsValueType(func.Outputs[0].Type!)
                        : "(" + string.Join(", ", func.Outputs.Select(o => $"{CsValueType(o.Type!)} {CsMemberName(o.Name)}")) + ")";
                    string result = func.Outputs.Count == 1
                        ? $"Output<{CsValueType(func.Outputs[0].Type!)}>(outputs, 0)"
                        : "(" + string.Join(", ", func.Outputs.Select((o, i) => $"Output<{CsValueType(o.Type!)}>(outputs, {i})")) + ")";
                    sb.Append($"    public async Task<{returnType}> {name}({parameters}CancellationToken ct = default)\n    {{\n");
                    sb.Append($"        IReadOnlyList<object> outputs = await {call}.ConfigureAwait(false);\n");
                    sb.Append($"        return {result};\n    }}\n");
                }
            }
            sb.Append("}\n");
        }
        return sb.ToString();
    }

    private string CsParameterName(string firmwareName)
    {
        string pascal = CsMemberName(firmwareName);
        return "@" + char.ToLowerInvariant(pascal[0]) + pascal[1..];
    }

    // ---------- JSON d'endpoints (generate_endpoint_table, interface_generator.py:478) ----------

    /// <summary>
    /// Reproduit le JSON embarqué dans le firmware. Sert uniquement à valider ce portage contre la sortie
    /// du générateur Python de référence (tools/gen_reference_json.py).
    /// </summary>
    public string EmitEndpointJson()
    {
        var sb = new StringBuilder("[{\"name\":\"\",\"id\":0,\"type\":\"json\",\"access\":\"r\"}");
        Table(_root, 1);
        return sb.Append(']').ToString();

        int Table(InterfaceDef intf, int idx)
        {
            int cnt = 0;
            foreach (var attr in intf.GetAllAttributes())
            {
                if (attr.Value is not null)
                {
                    sb.Append(',');
                    Property(attr.Name, idx + cnt, attr.Value, attr.ReadOnly);
                    cnt++;
                }
                else
                {
                    sb.Append($",{{\"name\":\"{attr.Name}\",\"type\":\"object\",\"members\":[");
                    int start = sb.Length;
                    cnt += Table(attr.SubObject!, idx + cnt);
                    if (sb.Length > start) sb.Remove(start, 1); // virgule de tête du premier membre
                    sb.Append("]}");
                }
            }
            foreach (var func in intf.GetAllFunctions())
            {
                // l.508-539 : la fonction, puis ses entrées (id+1…), puis ses sorties.
                int id = idx + cnt;
                sb.Append($",{{\"name\":\"{func.Name}\",\"id\":{id},\"type\":\"function\",\"inputs\":[");
                for (int i = 0; i < func.Inputs.Count; i++)
                {
                    if (i > 0) sb.Append(',');
                    Property(func.Inputs[i].Name, id + 1 + i, func.Inputs[i].Type!, readOnly: false);
                }
                sb.Append("],\"outputs\":[");
                for (int i = 0; i < func.Outputs.Count; i++)
                {
                    if (i > 0) sb.Append(',');
                    Property(func.Outputs[i].Name, id + 1 + func.Inputs.Count + i, func.Outputs[i].Type!, readOnly: true);
                }
                sb.Append("]}");
                cnt += 1 + func.Inputs.Count + func.Outputs.Count;
            }
            return cnt;
        }

        void Property(string name, int id, ValueTypeDef type, bool readOnly) =>
            sb.Append($"{{\"name\":\"{name}\",\"id\":{id},\"type\":\"{type.JsonType}\",\"access\":\"{(readOnly ? "r" : "rw")}\"}}");
    }

    // ---------- Littéraux ----------

    private static string Bool(bool value) => value ? "true" : "false";

    private static string? Summary(string? brief, string? doc)
    {
        string? text = brief ?? doc?.Split("\n\n")[0];
        return text is null ? null : string.Join(' ', text.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries));
    }

    private static string Xml(string text) => text.Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;");

    private static string Lit(string? text)
    {
        if (text is null) return "null";
        var sb = new StringBuilder("\"");
        foreach (char c in text.TrimEnd())
        {
            sb.Append(c switch
            {
                '"' => "\\\"",
                '\\' => "\\\\",
                '\n' => "\\n",
                '\r' => "",
                '\t' => "\\t",
                _ when c < ' ' => $"\\u{(int)c:X4}",
                _ => c.ToString(),
            });
        }
        return sb.Append('"').ToString();
    }
}
